-- V1 subscriptions: immutable plan versions, 30-day trial bridge, exact cycles and targeted entitlements.

create table public.subscription_plans (
 id uuid primary key default extensions.gen_random_uuid(),code text not null unique check(code in('PREMIUM','GOLD','PLATINUM')),status text not null default'DRAFT'check(status in('DRAFT','ACTIVE','RETIRED')),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp()
);
create table public.subscription_plan_versions (
 id uuid primary key default extensions.gen_random_uuid(),plan_id uuid not null references public.subscription_plans(id)on delete restrict,version integer not null check(version>0),status text not null check(status in('DRAFT','ACTIVE','RETIRED')),currency char(3)not null check(currency~'^[A-Z]{3}$'),monthly_price_minor bigint not null check(monthly_price_minor>=0),annual_price_minor bigint not null check(annual_price_minor>=0),monthly_credit_grant bigint not null check(monthly_credit_grant>=0),core_allocation_basis_points integer not null check(core_allocation_basis_points between 0 and 10000),benefit_pool_allocation_basis_points integer not null check(benefit_pool_allocation_basis_points between 0 and 10000),limits_snapshot jsonb not null check(jsonb_typeof(limits_snapshot)='object'),box_version_reference text,valid_from date not null,valid_to date,content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(plan_id,version),unique(plan_id,id),check(core_allocation_basis_points+benefit_pool_allocation_basis_points=10000),check(valid_to is null or valid_to>=valid_from)
);
create unique index subscription_plan_one_active_version_idx on public.subscription_plan_versions(plan_id)where status='ACTIVE';
create table public.plan_entitlements (
 id uuid primary key default extensions.gen_random_uuid(),plan_id uuid not null,plan_version_id uuid not null,entitlement_code text not null check(entitlement_code~'^[A-Z][A-Z0-9_]{2,79}$'),enabled boolean not null,quota_value bigint check(quota_value is null or quota_value>=0),configuration jsonb not null default'{}'check(jsonb_typeof(configuration)='object'),created_at timestamptz not null default clock_timestamp(),foreign key(plan_id,plan_version_id)references public.subscription_plan_versions(plan_id,id)on delete restrict,unique(plan_version_id,entitlement_code)
);
create table public.trial_entitlement_versions (
 id uuid primary key default extensions.gen_random_uuid(),entitlement_code text not null check(entitlement_code~'^[A-Z][A-Z0-9_]{2,79}$'),version integer not null check(version>0),status text not null check(status in('DRAFT','ACTIVE','RETIRED')),enabled boolean not null,quota_value bigint check(quota_value is null or quota_value>=0),configuration jsonb not null default'{}'check(jsonb_typeof(configuration)='object'),effective_from timestamptz not null,effective_to timestamptz,content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(entitlement_code,version),check(effective_to is null or effective_to>effective_from)
);
create unique index trial_entitlement_one_active_idx on public.trial_entitlement_versions(entitlement_code)where status='ACTIVE';
create table public.subscriptions (
 id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null unique references public.organizations(id)on delete restrict,client_trial_id uuid unique references public.client_trials(id)on delete restrict,plan_version_id uuid references public.subscription_plan_versions(id)on delete restrict,pending_plan_version_id uuid references public.subscription_plan_versions(id)on delete restrict,status text not null check(status in('TRIAL_ACTIVE','TRIAL_EXPIRED','ACTIVE','PAST_DUE','SUSPENDED','CANCELLED')),billing_interval text check(billing_interval is null or billing_interval in('MONTHLY','ANNUAL')),current_period_start timestamptz,current_period_end timestamptz,pending_change_effective_at timestamptz,row_version bigint not null default 1 check(row_version>0),created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(organization_id,id),check((status='ACTIVE')=(plan_version_id is not null and billing_interval is not null and current_period_start is not null and current_period_end is not null)or status<>'ACTIVE'),check(current_period_end is null or current_period_end>current_period_start),check((pending_plan_version_id is null)=(pending_change_effective_at is null))
);
create table public.subscription_cycles (
 id uuid primary key default extensions.gen_random_uuid(),subscription_id uuid not null references public.subscriptions(id)on delete restrict,organization_id uuid not null,plan_version_id uuid not null references public.subscription_plan_versions(id)on delete restrict,cycle_number integer not null check(cycle_number>0),period_start timestamptz not null,period_end timestamptz not null,currency char(3)not null check(currency~'^[A-Z]{3}$'),amount_minor bigint not null check(amount_minor>=0),payment_reference text not null,payment_proof_hash text not null check(payment_proof_hash~'^[0-9a-f]{64}$'),correlation_id uuid not null,created_at timestamptz not null default clock_timestamp(),foreign key(organization_id,subscription_id)references public.subscriptions(organization_id,id)on delete restrict,unique(subscription_id,cycle_number),unique(organization_id,payment_reference),check(period_end>period_start)
);
create table public.subscription_entitlement_suspensions (
 id uuid primary key default extensions.gen_random_uuid(),subscription_id uuid not null references public.subscriptions(id)on delete restrict,organization_id uuid not null,entitlement_code text not null check(entitlement_code~'^[A-Z][A-Z0-9_]{2,79}$'),reason_code text not null check(length(btrim(reason_code))between 3 and 80),reason_public text not null check(length(btrim(reason_public))between 3 and 1000),evidence_snapshot jsonb not null check(jsonb_typeof(evidence_snapshot)='object'),rule_version text not null check(length(btrim(rule_version))between 1 and 80),effective_from timestamptz not null,effective_to timestamptz,decided_by uuid not null references auth.users(id),correlation_id uuid not null,created_at timestamptz not null default clock_timestamp(),foreign key(organization_id,subscription_id)references public.subscriptions(organization_id,id)on delete restrict,check(effective_to is null or effective_to>effective_from)
);
create table public.subscription_state_events (
 id bigint generated always as identity primary key,subscription_id uuid not null references public.subscriptions(id)on delete restrict,organization_id uuid not null,from_status text,to_status text not null,reason_code text not null,idempotency_key text not null check(length(idempotency_key)between 8 and 200),correlation_id uuid not null,actor_user_id uuid not null references auth.users(id),occurred_at timestamptz not null default clock_timestamp(),foreign key(organization_id,subscription_id)references public.subscriptions(organization_id,id)on delete restrict,unique(subscription_id,idempotency_key)
);

create function private.subscription_admin_access(p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','FINANCE_MANAGER'],p_actor)$$;
create function private.subscription_read_access(p_org uuid,p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select private.has_org_role(p_org,array['CLIENT_OWNER','CLIENT_ADMIN','CLIENT_ACCOUNTING','CLIENT_VIEWER'],p_actor)or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','FINANCE_MANAGER','READ_ONLY_AUDITOR'],p_actor)$$;
create function private.begin_subscription_command(p_org uuid,p_scope text,p_key text,p_hash text,p_actor uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare v public.idempotency_keys%rowtype;n integer;begin if length(p_key)not between 8 and 200 or p_hash!~'^[0-9a-f]{64}$'then raise exception'INVALID_IDEMPOTENCY'using errcode='22023';end if;insert into public.idempotency_keys(organization_id,operation_scope,key,request_hash,created_by,expires_at)values(p_org,p_scope,p_key,p_hash,p_actor,now()+interval'30 days')on conflict do nothing;get diagnostics n=row_count;if n=1 then return null;end if;select*into v from public.idempotency_keys where organization_id=p_org and operation_scope=p_scope and key=p_key for update;if v.request_hash<>p_hash then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;if v.status='COMPLETED'then return v.response_body;end if;raise exception'IDEMPOTENCY_IN_PROGRESS'using errcode='55000';end$$;
create function private.finish_subscription_command(p_org uuid,p_scope text,p_key text,p_response jsonb)returns void language sql security definer set search_path=pg_catalog,public as $$update public.idempotency_keys set status='COMPLETED',response_code=201,response_body=p_response,completed_at=clock_timestamp()where organization_id=p_org and operation_scope=p_scope and key=p_key and status='PROCESSING'$$;

create function public.ensure_trial_subscription(p_organization_id uuid,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();t public.client_trials%rowtype;s uuid;h text;r jsonb;begin if a is null or not(private.has_org_role(p_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],a)or private.subscription_admin_access(a))then raise exception'SUBSCRIPTION_TRIAL_DENIED'using errcode='42501';end if;select*into t from public.client_trials where organization_id=p_organization_id for update;if not found then raise exception'VERIFIED_ACTIVATED_CLIENT_REQUIRED'using errcode='23514';end if;h:=private.canonical_request_hash(jsonb_build_object('organization',p_organization_id,'client_trial',t.id,'start',t.trial_started_at,'end',t.trial_ends_at));r:=private.begin_subscription_command(p_organization_id,'subscription.trial.ensure',p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.subscriptions(organization_id,client_trial_id,status)values(p_organization_id,t.id,case when t.status='TRIAL_ACTIVE'and t.trial_ends_at>clock_timestamp()then'TRIAL_ACTIVE'else'TRIAL_EXPIRED'end)returning id into s;r:=jsonb_build_object('outcome','TRIAL_SUBSCRIPTION_READY','subscription_id',s,'trial_started_at',t.trial_started_at,'trial_ends_at',t.trial_ends_at);insert into public.subscription_state_events(subscription_id,organization_id,from_status,to_status,reason_code,idempotency_key,correlation_id,actor_user_id)values(s,p_organization_id,null,case when t.status='TRIAL_ACTIVE'and t.trial_ends_at>clock_timestamp()then'TRIAL_ACTIVE'else'TRIAL_EXPIRED'end,'VERIFIED_ACTIVATED',p_idempotency_key,p_correlation_id,a);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','subscription.trial_ready','subscription',s::text,p_correlation_id,jsonb_build_object('client_trial_id',t.id),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'subscription',s::text,'TrialStartedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_subscription_command(p_organization_id,'subscription.trial.ensure',p_idempotency_key,r);return r;end$$;

create function public.activate_subscription(p_organization_id uuid,p_plan_version_id uuid,p_billing_interval text,p_period_start timestamptz,p_payment_reference text,p_payment_proof_hash text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();s public.subscriptions%rowtype;pv public.subscription_plan_versions%rowtype;amount bigint;finish timestamptz;cycle integer;h text;r jsonb;begin if a is null or not private.subscription_admin_access(a)then raise exception'SUBSCRIPTION_ACTIVATION_DENIED'using errcode='42501';end if;if p_billing_interval not in('MONTHLY','ANNUAL')or p_payment_proof_hash!~'^[0-9a-f]{64}$'or length(btrim(coalesce(p_payment_reference,'')))<3 then raise exception'INVALID_SUBSCRIPTION_ACTIVATION'using errcode='22023';end if;select*into s from public.subscriptions where organization_id=p_organization_id for update;if not found or s.status not in('TRIAL_ACTIVE','TRIAL_EXPIRED','PAST_DUE','SUSPENDED')then raise exception'SUBSCRIPTION_NOT_ACTIVATABLE'using errcode='55000';end if;select*into pv from public.subscription_plan_versions where id=p_plan_version_id and status='ACTIVE'and valid_from<=p_period_start::date and(valid_to is null or valid_to>=p_period_start::date);if not found then raise exception'ACTIVE_PLAN_VERSION_REQUIRED'using errcode='23514';end if;amount:=case when p_billing_interval='MONTHLY'then pv.monthly_price_minor else pv.annual_price_minor end;finish:=case when p_billing_interval='MONTHLY'then p_period_start+interval'1 month'else p_period_start+interval'1 year'end;h:=private.canonical_request_hash(jsonb_build_object('organization',p_organization_id,'plan_version',pv.id,'interval',p_billing_interval,'period_start',p_period_start,'payment_reference',p_payment_reference,'payment_proof_hash',p_payment_proof_hash));r:=private.begin_subscription_command(p_organization_id,'subscription.activate',p_idempotency_key,h,a);if r is not null then return r;end if;select coalesce(max(cycle_number),0)+1 into cycle from public.subscription_cycles where subscription_id=s.id;insert into public.subscription_cycles(subscription_id,organization_id,plan_version_id,cycle_number,period_start,period_end,currency,amount_minor,payment_reference,payment_proof_hash,correlation_id)values(s.id,p_organization_id,pv.id,cycle,p_period_start,finish,pv.currency,amount,p_payment_reference,p_payment_proof_hash,p_correlation_id);update public.subscriptions set plan_version_id=pv.id,pending_plan_version_id=null,status='ACTIVE',billing_interval=p_billing_interval,current_period_start=p_period_start,current_period_end=finish,pending_change_effective_at=null,row_version=row_version+1,updated_at=clock_timestamp()where id=s.id;r:=jsonb_build_object('outcome','SUBSCRIPTION_ACTIVATED','subscription_id',s.id,'plan_version_id',pv.id,'cycle_number',cycle,'period_end',finish,'amount_minor',amount,'currency',pv.currency);insert into public.subscription_state_events(subscription_id,organization_id,from_status,to_status,reason_code,idempotency_key,correlation_id,actor_user_id)values(s.id,p_organization_id,s.status,'ACTIVE','VERIFIED_PAYMENT',p_idempotency_key,p_correlation_id,a);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','subscription.activated','subscription',s.id::text,p_correlation_id,jsonb_build_object('plan_version_id',pv.id,'cycle_number',cycle),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'subscription',s.id::text,'SubscriptionPaidV1',p_correlation_id,r,p_idempotency_key);perform private.finish_subscription_command(p_organization_id,'subscription.activate',p_idempotency_key,r);return r;end$$;

create function public.change_subscription_plan(p_subscription_id uuid,p_target_plan_version_id uuid,p_change_mode text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();s public.subscriptions%rowtype;pv public.subscription_plan_versions%rowtype;h text;r jsonb;begin select*into s from public.subscriptions where id=p_subscription_id for update;if a is null or not found or s.status<>'ACTIVE'or not(private.has_org_role(s.organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],a)or private.subscription_admin_access(a))then raise exception'SUBSCRIPTION_CHANGE_DENIED'using errcode='42501';end if;if p_change_mode not in('UPGRADE_IMMEDIATE','DOWNGRADE_NEXT_CYCLE')then raise exception'INVALID_PLAN_CHANGE_MODE'using errcode='22023';end if;select*into pv from public.subscription_plan_versions where id=p_target_plan_version_id and status='ACTIVE'and valid_from<=current_date and(valid_to is null or valid_to>=current_date);if not found or pv.id=s.plan_version_id then raise exception'INVALID_TARGET_PLAN_VERSION'using errcode='23514';end if;h:=private.canonical_request_hash(jsonb_build_object('subscription',s.id,'target',pv.id,'mode',p_change_mode));r:=private.begin_subscription_command(s.organization_id,'subscription.plan.change',p_idempotency_key,h,a);if r is not null then return r;end if;if p_change_mode='UPGRADE_IMMEDIATE'then update public.subscriptions set plan_version_id=pv.id,row_version=row_version+1,updated_at=clock_timestamp()where id=s.id;else update public.subscriptions set pending_plan_version_id=pv.id,pending_change_effective_at=s.current_period_end,row_version=row_version+1,updated_at=clock_timestamp()where id=s.id;end if;r:=jsonb_build_object('outcome','SUBSCRIPTION_PLAN_CHANGED','subscription_id',s.id,'target_plan_version_id',pv.id,'change_mode',p_change_mode,'effective_at',case when p_change_mode='UPGRADE_IMMEDIATE'then clock_timestamp()else s.current_period_end end);insert into public.subscription_state_events(subscription_id,organization_id,from_status,to_status,reason_code,idempotency_key,correlation_id,actor_user_id)values(s.id,s.organization_id,'ACTIVE','ACTIVE',p_change_mode,p_idempotency_key,p_correlation_id,a);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(s.organization_id,a,'USER','subscription.plan_changed','subscription',s.id::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(s.organization_id,'subscription',s.id::text,'SubscriptionChangedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_subscription_command(s.organization_id,'subscription.plan.change',p_idempotency_key,r);return r;end$$;

create function public.subscription_has_entitlement(p_organization_id uuid,p_entitlement_code text,p_at timestamptz default clock_timestamp())returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$select private.subscription_read_access(p_organization_id,auth.uid())and case when exists(select 1 from public.client_trials t join public.trial_entitlement_versions te on te.entitlement_code=p_entitlement_code and te.status='ACTIVE'and te.enabled and te.effective_from<=p_at and(te.effective_to is null or te.effective_to>p_at)where t.organization_id=p_organization_id and t.status='TRIAL_ACTIVE'and p_at<t.trial_ends_at and not exists(select 1 from public.subscriptions s join public.subscription_entitlement_suspensions x on x.subscription_id=s.id where s.organization_id=p_organization_id and x.entitlement_code=p_entitlement_code and x.effective_from<=p_at and(x.effective_to is null or x.effective_to>p_at)))then true else exists(select 1 from public.subscriptions s join public.plan_entitlements e on e.plan_version_id=s.plan_version_id where s.organization_id=p_organization_id and s.status='ACTIVE'and p_at<s.current_period_end and e.entitlement_code=p_entitlement_code and e.enabled and not exists(select 1 from public.subscription_entitlement_suspensions x where x.subscription_id=s.id and x.entitlement_code=e.entitlement_code and x.effective_from<=p_at and(x.effective_to is null or x.effective_to>p_at)))end$$;

do $$declare t text;begin foreach t in array array['subscription_plans','subscription_plan_versions','plan_entitlements','trial_entitlement_versions','subscriptions','subscription_cycles','subscription_entitlement_suspensions','subscription_state_events']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);end loop;end$$;
create policy plans_read on public.subscription_plans for select to authenticated using(status='ACTIVE'or private.subscription_admin_access());create policy plan_versions_read on public.subscription_plan_versions for select to authenticated using(status='ACTIVE'or private.subscription_admin_access());create policy entitlements_read on public.plan_entitlements for select to authenticated using(exists(select 1 from public.subscription_plan_versions v where v.id=plan_version_id and(v.status='ACTIVE'or private.subscription_admin_access())));create policy trial_entitlements_read on public.trial_entitlement_versions for select to authenticated using(status='ACTIVE'or private.subscription_admin_access());create policy subscriptions_tenant_read on public.subscriptions for select to authenticated using(private.subscription_read_access(organization_id));create policy cycles_tenant_read on public.subscription_cycles for select to authenticated using(private.subscription_read_access(organization_id));create policy suspensions_tenant_read on public.subscription_entitlement_suspensions for select to authenticated using(private.subscription_read_access(organization_id));create policy state_events_tenant_read on public.subscription_state_events for select to authenticated using(private.subscription_read_access(organization_id));
grant select on public.subscription_plans,public.subscription_plan_versions,public.plan_entitlements,public.trial_entitlement_versions,public.subscriptions,public.subscription_cycles,public.subscription_entitlement_suspensions,public.subscription_state_events to authenticated;
create trigger subscription_plan_versions_immutable before update or delete on public.subscription_plan_versions for each row execute function private.prevent_update_delete();create trigger plan_entitlements_immutable before update or delete on public.plan_entitlements for each row execute function private.prevent_update_delete();create trigger trial_entitlements_immutable before update or delete on public.trial_entitlement_versions for each row execute function private.prevent_update_delete();create trigger subscription_cycles_immutable before update or delete on public.subscription_cycles for each row execute function private.prevent_update_delete();create trigger entitlement_suspensions_immutable before update or delete on public.subscription_entitlement_suspensions for each row execute function private.prevent_update_delete();create trigger subscription_state_events_immutable before update or delete on public.subscription_state_events for each row execute function private.prevent_update_delete();
revoke all on function private.subscription_admin_access(uuid),private.subscription_read_access(uuid,uuid),private.begin_subscription_command(uuid,text,text,text,uuid),private.finish_subscription_command(uuid,text,text,jsonb)from public,anon,authenticated,service_role;grant execute on function private.subscription_admin_access(uuid),private.subscription_read_access(uuid,uuid)to authenticated;
revoke all on function public.ensure_trial_subscription(uuid,text,uuid),public.activate_subscription(uuid,uuid,text,timestamptz,text,text,text,uuid),public.change_subscription_plan(uuid,uuid,text,text,uuid),public.subscription_has_entitlement(uuid,text,timestamptz)from public,anon,authenticated,service_role;grant execute on function public.ensure_trial_subscription(uuid,text,uuid),public.activate_subscription(uuid,uuid,text,timestamptz,text,text,text,uuid),public.change_subscription_plan(uuid,uuid,text,text,uuid),public.subscription_has_entitlement(uuid,text,timestamptz)to authenticated;
create index subscription_plan_versions_active_idx on public.subscription_plan_versions(status,valid_from,valid_to);create index subscriptions_org_status_idx on public.subscriptions(organization_id,status,current_period_end);create index subscription_cycles_time_idx on public.subscription_cycles(subscription_id,period_end desc);create index entitlement_suspensions_active_idx on public.subscription_entitlement_suspensions(subscription_id,entitlement_code,effective_from,effective_to);create index subscription_state_events_time_idx on public.subscription_state_events(subscription_id,occurred_at desc,id desc);
